package cn.yuanxin.mvp.web.notifications;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

import java.util.Map;

/**
 * M5-A01 请求/响应形状（contracts/openapi NotificationDestinationRequest /
 * NotificationDestinationView）。
 *
 * <p>请求 {@code additionalProperties:false}：全局
 * {@code spring.jackson.deserialization.fail-on-unknown-properties=true}
 * 会把未知字段（如伪造的 accountId/installationId）转成 400 INVALID_INPUT；
 * 身份只来自 token。</p>
 *
 * <p>响应只含 destinationId/destinationRevision/status——绝不回传完整推送
 * token / registration（契约响应体没有该字段）。destinationRevision 是
 * bigint，出 JSON 用十进制字符串（契约 BigintString）。</p>
 */
public final class NotificationDestinationDtos {

    private NotificationDestinationDtos() {
    }

    /** M5-A01 请求体；platform 用 String 以便对非 android 值给出明确 400。 */
    public record Request(
            @NotBlank @Size(max = 64) String provider,
            @NotBlank @Size(max = 32) String platform,
            @NotNull Map<String, Object> registration,
            @NotBlank @Pattern(regexp = "^(0|[1-9][0-9]*)$",
                    message = "expectedDestinationRevision must be an unsigned decimal bigint string")
            String expectedDestinationRevision) {
    }

    /** M5-A01 响应体：恰好三个字段。 */
    public record View(String destinationId, String destinationRevision, String status) {
    }
}

package cn.yuanxin.mvp.web.notifications;

import cn.yuanxin.mvp.web.auth.PrincipalContext;
import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;
import cn.yuanxin.mvp.web.idempotency.BeginOutcome;
import cn.yuanxin.mvp.web.idempotency.CanonicalObjectBuilder;
import cn.yuanxin.mvp.web.idempotency.IdempotencyHandle;
import cn.yuanxin.mvp.web.idempotency.IdempotencyService;
import cn.yuanxin.mvp.web.idempotency.Jcs;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

/**
 * M5-A01 目标登记业务（DD M5-A01；lane-m5 第一部分）。
 *
 * <p>每条目标落在 T09 {@code notification_destinations}（installation_id 唯一）。
 * 事务内先 {@code SELECT ... FOR UPDATE}，再按"行不存在 / 同账号 / 换号"三分支
 * 做<b>字段级</b>写入；首建并发用
 * {@code INSERT ... ON CONFLICT (installation_id) DO NOTHING} 去重（不靠捕获
 * 异常导致事务 abort）。</p>
 *
 * <p><b>代次/换号语义</b>：相同内容不递增 {@code destination_revision}（但刷新
 * {@code session_ref} 使旧会话失效）；内容变化或换号接管都
 * {@code destination_revision + 1}，使旧账号/旧内容的通知路由快照全部失配。
 * {@code expectedDestinationRevision} 不符复用 409 {@code BINDING_CHANGED}
 * ——契约无"目标代次不符"专用码且 B 不得新增错误码；DD 3.2 该码语义正是
 * "刷新当前状态并重新操作；旧请求不得改写新事实"，details 只含
 * {@code currentDestinationRevision}（不泄漏其他账号信息）。</p>
 */
@Service
public class NotificationDestinationService {

    /** 契约固定 operation（canonicalObject 首键）。 */
    public static final String OPERATION = "m5-a01-register-notification-destination";

    private static final String RESOURCE_TYPE = "notification_destination";

    private static final String SELECT_FOR_UPDATE =
            "SELECT id, account_id, destination_revision, provider, platform,"
                    + " registration::text AS registration, status, session_ref"
                    + " FROM notification_destinations WHERE installation_id = ? FOR UPDATE";

    private static final String SELECT_BY_ID =
            "SELECT id, account_id, destination_revision, status"
                    + " FROM notification_destinations WHERE id = ?";

    private final JdbcTemplate jdbc;
    private final TransactionTemplate txTemplate;
    private final IdempotencyService idempotencyService;
    private final ObjectMapper objectMapper;

    public NotificationDestinationService(JdbcTemplate jdbc, TransactionTemplate txTemplate,
                                          IdempotencyService idempotencyService,
                                          ObjectMapper objectMapper) {
        this.jdbc = jdbc;
        this.txTemplate = txTemplate;
        this.idempotencyService = idempotencyService;
        this.objectMapper = objectMapper;
    }

    /** 登记结果：响应投影 + 是否 T13 重放。 */
    public record RegisterResult(String destinationId, String destinationRevision,
                                 String status, boolean replayed) {
    }

    /** 业务事务返回：成功投影，或需在提交后抛出的确定性拒绝。 */
    private record TxOutcome(RegisterResult result, ApiException rejection) {
    }

    /** T09 行快照（FOR UPDATE 读）。 */
    private record DestinationRow(UUID id, UUID accountId, long revision, String provider,
                                  String platform, String registrationText, String status,
                                  String sessionRef) {
    }

    public RegisterResult register(PrincipalContext principal, String installationId,
                                   NotificationDestinationDtos.Request body, String idempotencyKey) {
        Map<String, Object> effectiveRegistration = normalizeRegistration(body.registration());
        String payloadHash = canonicalHash(principal, installationId, body, effectiveRegistration);

        BeginOutcome outcome = idempotencyService.begin(principal.t13PrincipalType(),
                principal.t13PrincipalId(), OPERATION, idempotencyKey, payloadHash);
        IdempotencyHandle handle;
        switch (outcome) {
            case BeginOutcome.ReplaySucceeded replay -> {
                return projectReplay(replay, principal);
            }
            case BeginOutcome.ReplayRejected rejected ->
                    throw IdempotencyService.replayedRejection(rejected);
            case BeginOutcome.NewAttempt fresh -> handle = fresh.handle();
        }

        TxOutcome txOutcome = txTemplate.execute(status ->
                applyRegistration(handle, principal, installationId, body, effectiveRegistration));
        if (txOutcome == null) {
            throw new ApiException(ErrorCode.INTERNAL, "registration transaction returned no outcome");
        }
        if (txOutcome.rejection() != null) {
            throw txOutcome.rejection();
        }
        return txOutcome.result();
    }

    // ---------------- transactional core ----------------

    private TxOutcome applyRegistration(IdempotencyHandle handle, PrincipalContext principal,
                                        String installationId, NotificationDestinationDtos.Request body,
                                        Map<String, Object> effectiveRegistration) {
        List<DestinationRow> rows = jdbc.query(SELECT_FOR_UPDATE,
                (rs, i) -> new DestinationRow(
                        rs.getObject("id", UUID.class),
                        rs.getObject("account_id", UUID.class),
                        rs.getLong("destination_revision"),
                        rs.getString("provider"),
                        rs.getString("platform"),
                        rs.getString("registration"),
                        rs.getString("status"),
                        rs.getString("session_ref")),
                installationId);

        if (rows.isEmpty()) {
            if (!"0".equals(body.expectedDestinationRevision())) {
                return reject(handle, currentRevisionDetails(0L));
            }
            UUID destinationId = UUID.randomUUID();
            int inserted = jdbc.update("INSERT INTO notification_destinations"
                            + " (id, installation_id, account_id, destination_revision, provider,"
                            + " platform, registration, status, session_ref, last_registered_at,"
                            + " invalidated_at)"
                            + " VALUES (?, ?, ?, 1, ?, ?, ?::jsonb, 'active', ?, now(), NULL)"
                            + " ON CONFLICT (installation_id) DO NOTHING",
                    destinationId, installationId, principal.accountUuid(), body.provider(),
                    body.platform(), writeJson(effectiveRegistration), principal.sessionId());
            if (inserted == 1) {
                idempotencyService.completeSuccess(handle, RESOURCE_TYPE, destinationId,
                        Map.of("destinationId", destinationId.toString(),
                                "destinationRevision", "1", "status", "active"));
                return ok(destinationId, 1L, "active");
            }
            // 并发首建落败：改走"行已存在"分支（不 500）。
            rows = jdbc.query(SELECT_FOR_UPDATE,
                    (rs, i) -> new DestinationRow(
                            rs.getObject("id", UUID.class),
                            rs.getObject("account_id", UUID.class),
                            rs.getLong("destination_revision"),
                            rs.getString("provider"), rs.getString("platform"),
                            rs.getString("registration"), rs.getString("status"),
                            rs.getString("session_ref")),
                    installationId);
            if (rows.isEmpty()) {
                throw new ApiException(ErrorCode.INTERNAL, "destination conflict resolution lost row");
            }
        }

        DestinationRow row = rows.get(0);
        if (row.accountId() != null && row.accountId().equals(principal.accountUuid())) {
            return sameAccount(handle, principal, body, effectiveRegistration, row);
        }
        return accountSwitch(handle, principal, body, effectiveRegistration, row);
    }

    private TxOutcome sameAccount(IdempotencyHandle handle, PrincipalContext principal,
                                  NotificationDestinationDtos.Request body,
                                  Map<String, Object> effectiveRegistration, DestinationRow row) {
        if (!body.expectedDestinationRevision().equals(String.valueOf(row.revision()))) {
            return reject(handle, currentRevisionDetails(row.revision()));
        }
        boolean sameContent = body.provider().equals(row.provider())
                && body.platform().equals(row.platform())
                && canonicalJson(effectiveRegistration).equals(canonicalOfText(row.registrationText()));
        if (sameContent) {
            // 相同内容不递增代次；但刷新会话引用使旧会话目标失效（同账号重登录）。
            jdbc.update("UPDATE notification_destinations"
                            + " SET session_ref = ?, last_registered_at = now(), status = 'active',"
                            + " invalidated_at = NULL, updated_at = now()"
                            + " WHERE id = ?",
                    principal.sessionId(), row.id());
            idempotencyService.completeSuccess(handle, RESOURCE_TYPE, row.id(),
                    summary(row.id(), row.revision(), "active"));
            return ok(row.id(), row.revision(), "active");
        }
        int updated = jdbc.update("UPDATE notification_destinations"
                        + " SET provider = ?, platform = ?, registration = ?::jsonb, session_ref = ?,"
                        + " last_registered_at = now(), status = 'active', invalidated_at = NULL,"
                        + " destination_revision = destination_revision + 1, updated_at = now()"
                        + " WHERE id = ? AND destination_revision = ?",
                body.provider(), body.platform(), writeJson(effectiveRegistration),
                principal.sessionId(), row.id(), row.revision());
        if (updated == 0) {
            throw ApiException.requestInProgress(1);
        }
        long nextRevision = row.revision() + 1;
        idempotencyService.completeSuccess(handle, RESOURCE_TYPE, row.id(),
                summary(row.id(), nextRevision, "active"));
        return ok(row.id(), nextRevision, "active");
    }

    /**
     * 换号接管（SC-01-17）：调用方用 token 证明了对该安装实例的控制
     * （installationId 来自 token），允许接管。契约没有 GET 目标端点，
     * 换号方读不到当前代次，因此接受 {@code "0"} 或当前值；随后
     * {@code destination_revision + 1} 使旧账号快照全部失效。
     */
    private TxOutcome accountSwitch(IdempotencyHandle handle, PrincipalContext principal,
                                    NotificationDestinationDtos.Request body,
                                    Map<String, Object> effectiveRegistration, DestinationRow row) {
        String expected = body.expectedDestinationRevision();
        if (!"0".equals(expected) && !expected.equals(String.valueOf(row.revision()))) {
            return reject(handle, currentRevisionDetails(row.revision()));
        }
        int updated = jdbc.update("UPDATE notification_destinations"
                        + " SET account_id = ?, session_ref = ?, provider = ?, platform = ?,"
                        + " registration = ?::jsonb, status = 'active', invalidated_at = NULL,"
                        + " last_registered_at = now(), destination_revision = destination_revision + 1,"
                        + " updated_at = now()"
                        + " WHERE id = ? AND destination_revision = ?",
                principal.accountUuid(), principal.sessionId(), body.provider(), body.platform(),
                writeJson(effectiveRegistration), row.id(), row.revision());
        if (updated == 0) {
            throw ApiException.requestInProgress(1);
        }
        long nextRevision = row.revision() + 1;
        idempotencyService.completeSuccess(handle, RESOURCE_TYPE, row.id(),
                summary(row.id(), nextRevision, "active"));
        return ok(row.id(), nextRevision, "active");
    }

    // ---------------- replay ----------------

    /**
     * T13 重放：只定位原资源并按当前 T09 状态投影，不重做写入。若该行当前已
     * 归属其他账号（安装实例被接管），视为对当前主体不可见 → 同一 404
     * RESOURCE_NOT_VISIBLE（不泄漏存在性）。
     */
    private RegisterResult projectReplay(BeginOutcome.ReplaySucceeded replay,
                                         PrincipalContext principal) {
        if (!RESOURCE_TYPE.equals(replay.resourceType()) || replay.resourceId() == null) {
            throw new ApiException(ErrorCode.INTERNAL, "unexpected replay resource");
        }
        List<DestinationRow> rows = jdbc.query(SELECT_BY_ID,
                (rs, i) -> new DestinationRow(rs.getObject("id", UUID.class),
                        rs.getObject("account_id", UUID.class), rs.getLong("destination_revision"),
                        null, null, null, rs.getString("status"), null),
                replay.resourceId());
        if (rows.isEmpty() || rows.get(0).accountId() == null
                || !rows.get(0).accountId().equals(principal.accountUuid())) {
            throw new ApiException(ErrorCode.RESOURCE_NOT_VISIBLE, "destination not visible");
        }
        DestinationRow row = rows.get(0);
        return new RegisterResult(row.id().toString(), String.valueOf(row.revision()),
                row.status(), true);
    }

    // ---------------- helpers ----------------

    /**
     * 注册资料规范化：空对象 → 400（active 行要求非空注册）；缺
     * {@code schema_version} 时服务端注入整数 1；显式给出但非 JSON 整数 →
     * 400（不静默改写，也避免 DB CHECK 直接报错）。
     */
    static Map<String, Object> normalizeRegistration(Map<String, Object> raw) {
        Map<String, Object> copy = new LinkedHashMap<>(raw);
        if (copy.isEmpty()) {
            throw invalidInput("registration must be a non-empty object");
        }
        Object version = copy.get("schema_version");
        if (version == null) {
            copy.put("schema_version", 1);
            return copy;
        }
        if (!isIntegralJsonNumber(version)) {
            throw invalidInput("registration.schema_version must be a JSON integer");
        }
        return copy;
    }

    private static boolean isIntegralJsonNumber(Object value) {
        return value instanceof Integer || value instanceof Long || value instanceof Short
                || value instanceof Byte || value instanceof java.math.BigInteger;
    }

    private static ApiException invalidInput(String message) {
        return new ApiException(ErrorCode.INVALID_INPUT, message);
    }

    private static ApiException bindingChanged() {
        return new ApiException(ErrorCode.BINDING_CHANGED,
                "destination revision changed; refresh current state and retry");
    }

    private static Map<String, Object> currentRevisionDetails(long revision) {
        return Map.of("currentDestinationRevision", String.valueOf(revision));
    }

    private TxOutcome reject(IdempotencyHandle handle, Map<String, Object> details) {
        idempotencyService.completeRejected(handle, ErrorCode.BINDING_CHANGED,
                ErrorCode.BINDING_CHANGED.defaultStatus().value(),
                "destination revision changed; refresh current state and retry", false, details);
        return new TxOutcome(null, bindingChanged());
    }

    private static TxOutcome ok(UUID id, long revision, String status) {
        return new TxOutcome(new RegisterResult(id.toString(), String.valueOf(revision),
                status, false), null);
    }

    private static Map<String, Object> summary(UUID id, long revision, String status) {
        Map<String, Object> map = new LinkedHashMap<>();
        map.put("destinationId", id.toString());
        map.put("destinationRevision", String.valueOf(revision));
        map.put("status", status);
        return map;
    }

    private String canonicalHash(PrincipalContext principal, String installationId,
                                 NotificationDestinationDtos.Request body,
                                 Map<String, Object> effectiveRegistration) {
        Map<String, Object> fields = new LinkedHashMap<>();
        fields.put("provider", body.provider());
        fields.put("platform", body.platform());
        fields.put("registration", effectiveRegistration);
        fields.put("expectedDestinationRevision", body.expectedDestinationRevision());
        fields.put("accountId", principal.accountUuid().toString());
        fields.put("installationId", installationId);
        return CanonicalObjectBuilder.forOperation(OPERATION)
                .pathParams(Map.of("installationId", installationId))
                .fields(fields)
                .payloadHash();
    }

    private static String canonicalJson(Map<String, Object> value) {
        return Jcs.canonicalize(Jcs.toNode(value));
    }

    private static String canonicalOfText(String jsonbText) {
        return Jcs.canonicalize(Jcs.parseStrict(jsonbText));
    }

    private String writeJson(Map<String, Object> value) {
        try {
            return objectMapper.writeValueAsString(value);
        } catch (JsonProcessingException e) {
            throw invalidInput("registration is not JSON-serializable");
        }
    }
}

package cn.yuanxin.mvp.web.notifications;

import cn.yuanxin.mvp.web.auth.PrincipalContext;
import cn.yuanxin.mvp.web.auth.PrincipalType;
import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;
import cn.yuanxin.mvp.web.web.EnvelopeSupport;
import cn.yuanxin.mvp.web.web.SuccessEnvelope;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.Valid;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * M5-A01 {@code PUT /api/v1/me/notification-destinations/{installationId}}：
 * 已登录 APP 登记本安装实例的推送目标（DD M5-A01；lane-m5 第一部分）。
 *
 * <ul>
 *   <li>主体**仅 APP**（云台 token → 403 CALLER_NOT_ALLOWED）；身份只来自 token。</li>
 *   <li>路径 {@code installationId} 必须**等于** {@code principal.installationId()}，
 *       否则 403 CALLER_NOT_ALLOWED——不能仅凭 installationId 抢占或替他人登记；
 *       路径空白/超 128 → 400 INVALID_INPUT。</li>
 *   <li>请求体 platform 仅 android；registration 非空且 schema_version 为整数；
 *       {@code Idempotency-Key} 必填。</li>
 *   <li>响应只含 destinationId/destinationRevision/status，永不回传推送 token；
 *       header {@code Cache-Control: no-store}（X-Request-Id 由 RequestIdFilter 统一加）。</li>
 *   <li>本接口只登记目标，**不发送任何消息**。</li>
 * </ul>
 */
@RestController
@RequestMapping("/api/v1/me/notification-destinations")
public class NotificationDestinationController {

    private final NotificationDestinationService service;
    private final EnvelopeSupport envelopes;

    public NotificationDestinationController(NotificationDestinationService service,
                                             EnvelopeSupport envelopes) {
        this.service = service;
        this.envelopes = envelopes;
    }

    @PutMapping("/{installationId}")
    public ResponseEntity<SuccessEnvelope> register(
            @PathVariable("installationId") String installationId,
            @Valid @RequestBody NotificationDestinationDtos.Request body,
            @RequestHeader(value = "Idempotency-Key", required = false) String idempotencyKey,
            PrincipalContext principal,
            HttpServletRequest request) {
        requireApp(principal);
        requireMatchingInstallation(installationId, principal);
        requireIdempotencyKey(idempotencyKey);
        requireAndroid(body.platform());

        NotificationDestinationService.RegisterResult result =
                service.register(principal, installationId, body, idempotencyKey);
        NotificationDestinationDtos.View view = new NotificationDestinationDtos.View(
                result.destinationId(), result.destinationRevision(), result.status());
        return ResponseEntity.ok()
                .header("Cache-Control", "no-store")
                .body(envelopes.ok(request, view, result.replayed()));
    }

    private static void requireApp(PrincipalContext principal) {
        if (principal.principalType() != PrincipalType.APP) {
            throw new ApiException(ErrorCode.CALLER_NOT_ALLOWED,
                    "this endpoint is only available to app account sessions");
        }
    }

    private static void requireMatchingInstallation(String installationId, PrincipalContext principal) {
        if (installationId == null || installationId.isBlank() || installationId.length() > 128) {
            throw new ApiException(ErrorCode.INVALID_INPUT,
                    "installationId must be 1-128 characters");
        }
        if (!installationId.equals(principal.installationId())) {
            throw new ApiException(ErrorCode.CALLER_NOT_ALLOWED,
                    "installationId does not belong to the authenticated session");
        }
    }

    private static void requireIdempotencyKey(String key) {
        if (key == null || key.isBlank() || key.length() > 128) {
            throw new ApiException(ErrorCode.INVALID_INPUT,
                    "Idempotency-Key header is required (1-128 characters)");
        }
    }

    private static void requireAndroid(String platform) {
        if (!"android".equals(platform)) {
            throw new ApiException(ErrorCode.INVALID_INPUT, "platform must be android");
        }
    }
}

package cn.yuanxin.mvp.web.notifications;

import cn.yuanxin.mvp.web.support.AbstractWebIT;
import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MvcResult;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.Callable;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;
import java.util.stream.StreamSupport;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put;

/**
 * M5-A01（通知目标登记）真实 PG 集成测试：首建、响应最小化、相同内容不增代次、
 * 内容变化增代次、代次冲突、换号接管、越权/无效主体、幂等重放、并发首建、
 * 会话失效。
 *
 * <p>覆盖 lane-m5.md Java 必测 1～10。身份只来自 token；DB 断言在行级
 * （字段值 / 计数），不只看 HTTP 码。</p>
 */
class NotificationDestinationsIT extends AbstractWebIT {

    private static final String PROVIDER = "dev-fcm";
    private static final String PLATFORM = "android";

    @Autowired
    JdbcTemplate jdbc;

    // ---------------- helpers ----------------

    private record Dest(UUID id, UUID accountId, long revision, String provider, String platform,
                        String registration, String status, String sessionRef,
                        boolean invalidated) {
    }

    private static String body(String provider, String platform,
                               Map<String, Object> registration, String expected)
            throws Exception {
        Map<String, Object> m = new LinkedHashMap<>();
        m.put("provider", provider);
        m.put("platform", platform);
        m.put("registration", registration);
        m.put("expectedDestinationRevision", expected);
        return JSON.writeValueAsString(m);
    }

    private static Map<String, Object> registration(String token) {
        Map<String, Object> reg = new LinkedHashMap<>();
        reg.put("token", token);
        return reg;
    }

    private MvcResult putJson(String token, String installationId, String json, String key)
            throws Exception {
        var builder = put("/api/v1/me/notification-destinations/" + installationId)
                .contentType("application/json").content(json);
        if (token != null) {
            builder.header("Authorization", "Bearer " + token);
        }
        if (key != null) {
            builder.header("Idempotency-Key", key);
        }
        return mockMvc.perform(builder).andReturn();
    }

    private Dest destOf(String installationId) {
        List<Dest> rows = jdbc.query("SELECT id, account_id, destination_revision, provider,"
                        + " platform, registration::text AS registration, status, session_ref,"
                        + " invalidated_at FROM notification_destinations WHERE installation_id = ?",
                (rs, i) -> new Dest(rs.getObject("id", UUID.class),
                        rs.getObject("account_id", UUID.class), rs.getLong("destination_revision"),
                        rs.getString("provider"), rs.getString("platform"),
                        rs.getString("registration"), rs.getString("status"),
                        rs.getString("session_ref"), rs.getTimestamp("invalidated_at") != null),
                installationId);
        return rows.isEmpty() ? null : rows.get(0);
    }

    private long destCount(String installationId) {
        Long n = jdbc.queryForObject(
                "SELECT count(*) FROM notification_destinations WHERE installation_id = ?",
                Long.class, installationId);
        return n == null ? 0 : n;
    }

    private static JsonNode data(MvcResult r) throws Exception {
        return JSON.readTree(r.getResponse().getContentAsString()).path("data");
    }

    private static JsonNode error(MvcResult r) throws Exception {
        return JSON.readTree(r.getResponse().getContentAsString()).path("error");
    }

    private UUID seedGimbal() {
        UUID id = UUID.randomUUID();
        jdbc.update("INSERT INTO gimbals (id, serial_no, auth_subject_ref, credential_version)"
                        + " VALUES (?, ?, ?, 1)",
                id, "gimbal-notif-" + id, "cred-" + id);
        return id;
    }

    private String gimbalToken(UUID gimbalId) throws Exception {
        MvcResult result = mockMvc.perform(post("/api/v1/gimbal-sessions")
                        .contentType("application/json")
                        .content("{\"credential\":\"cred-" + gimbalId
                                + "\",\"credentialVersion\":\"1\",\"proof\":\"dev-proof\"}"))
                .andReturn();
        assertEquals(200, result.getResponse().getStatus(),
                result.getResponse().getContentAsString());
        return data(result).path("sessionToken").asText();
    }

    // ---------------- 1. first registration ----------------

    @Test
    @DisplayName("1 首次登记 expected=0 → 200 active revision=1；DB 行含账号/会话/注册（整数 schema_version）")
    void firstRegistrationCreatesActiveRow() throws Exception {
        String phone = newPhone();
        String installation = "inst-first";
        LoginResult login = loginAppWithInstallation(phone, installation);

        MvcResult r = putJson(login.accessToken(), installation,
                body(PROVIDER, PLATFORM, registration("tok-1"), "0"), "k-" + UUID.randomUUID());
        assertEquals(200, r.getResponse().getStatus(), r.getResponse().getContentAsString());
        assertEquals("active", data(r).path("status").asText());
        assertEquals("1", data(r).path("destinationRevision").asText());
        assertNotNull(data(r).path("destinationId").asText(null));
        assertEquals("no-store", r.getResponse().getHeader("Cache-Control"));

        Dest dest = destOf(installation);
        assertNotNull(dest);
        assertEquals(UUID.fromString(login.accountId()), dest.accountId());
        assertEquals(1L, dest.revision());
        assertEquals(PROVIDER, dest.provider());
        assertEquals(PLATFORM, dest.platform());
        assertEquals("active", dest.status());
        assertNotNull(dest.sessionRef());
        assertEquals("1", jdbc.queryForObject("SELECT registration ->> 'schema_version'"
                + " FROM notification_destinations WHERE installation_id = ?", String.class,
                installation));
        assertEquals("number", jdbc.queryForObject("SELECT jsonb_typeof(registration ->"
                + " 'schema_version') FROM notification_destinations WHERE installation_id = ?",
                String.class, installation));
        assertFalse(dest.invalidated());
        assertNotNull(jdbc.queryForObject("SELECT last_registered_at FROM notification_destinations"
                + " WHERE installation_id = ?", java.sql.Timestamp.class, installation));
    }

    // ---------------- 2. response minimal ----------------

    @Test
    @DisplayName("2 响应体只含 destinationId/destinationRevision/status（绝不回传推送 token）")
    void responseContainsOnlyThreeFields() throws Exception {
        String installation = "inst-fields";
        LoginResult login = loginAppWithInstallation(newPhone(), installation);
        MvcResult r = putJson(login.accessToken(), installation,
                body(PROVIDER, PLATFORM, registration("secret-token-value"), "0"),
                "k-" + UUID.randomUUID());
        assertEquals(200, r.getResponse().getStatus());

        JsonNode d = data(r);
        Set<String> fieldNames = StreamSupport.stream(
                        ((Iterable<String>) () -> d.fieldNames()).spliterator(), false)
                .collect(Collectors.toSet());
        assertEquals(Set.of("destinationId", "destinationRevision", "status"), fieldNames);
        assertFalse(r.getResponse().getContentAsString().contains("secret-token-value"));
    }

    // ---------------- 3. same content / session refresh ----------------

    @Test
    @DisplayName("3 相同内容重复 PUT 同代次 → revision 不增；session_ref 刷新为当前会话")
    void sameContentKeepsRevisionButRefreshesSession() throws Exception {
        String phone = newPhone();
        String installation = "inst-same";
        LoginResult first = loginAppWithInstallation(phone, installation);
        String firstSession = sessionIdOf(first.accessToken());

        MvcResult created = putJson(first.accessToken(), installation,
                body(PROVIDER, PLATFORM, registration("tok"), "0"), "k-" + UUID.randomUUID());
        assertEquals(200, created.getResponse().getStatus());
        assertEquals(firstSession, destOf(installation).sessionRef());

        // 同一账号重新登录（新会话），相同内容 + 当前代次
        LoginResult second = loginAppWithInstallation(phone, installation);
        String secondSession = sessionIdOf(second.accessToken());
        assertNotEquals(firstSession, secondSession);

        MvcResult updated = putJson(second.accessToken(), installation,
                body(PROVIDER, PLATFORM, registration("tok"), "1"), "k-" + UUID.randomUUID());
        assertEquals(200, updated.getResponse().getStatus(), updated.getResponse().getContentAsString());
        assertEquals("1", data(updated).path("destinationRevision").asText());
        Dest dest = destOf(installation);
        assertEquals(1L, dest.revision(), "相同内容不得递增 destination_revision");
        assertEquals(secondSession, dest.sessionRef(), "session_ref 必须刷新为当前会话");
    }

    // ---------------- 4. changed content bumps revision ----------------

    @Test
    @DisplayName("4 内容变化 → 200 且 destination_revision +1")
    void changedContentBumpsRevision() throws Exception {
        String installation = "inst-change";
        LoginResult login = loginAppWithInstallation(newPhone(), installation);
        assertEquals(200, putJson(login.accessToken(), installation,
                body(PROVIDER, PLATFORM, registration("a"), "0"), "k-" + UUID.randomUUID())
                .getResponse().getStatus());

        MvcResult r = putJson(login.accessToken(), installation,
                body("dev-huawei", PLATFORM, registration("b"), "1"), "k-" + UUID.randomUUID());
        assertEquals(200, r.getResponse().getStatus(), r.getResponse().getContentAsString());
        assertEquals("2", data(r).path("destinationRevision").asText());
        Dest dest = destOf(installation);
        assertEquals(2L, dest.revision());
        assertEquals("dev-huawei", dest.provider());
    }

    // ---------------- 5. stale expected revision ----------------

    @Test
    @DisplayName("5 expectedDestinationRevision 不符 → 409 BINDING_CHANGED，details 只含 currentDestinationRevision，T09 未变")
    void staleExpectedRevisionConflicts() throws Exception {
        String installation = "inst-stale";
        LoginResult login = loginAppWithInstallation(newPhone(), installation);
        assertEquals(200, putJson(login.accessToken(), installation,
                body(PROVIDER, PLATFORM, registration("tok"), "0"), "k-" + UUID.randomUUID())
                .getResponse().getStatus());
        Dest before = destOf(installation);

        MvcResult r = putJson(login.accessToken(), installation,
                body(PROVIDER, PLATFORM, registration("tok"), "0"), "k-" + UUID.randomUUID());
        assertEquals(409, r.getResponse().getStatus(), r.getResponse().getContentAsString());
        assertEquals("BINDING_CHANGED", error(r).path("code").asText());
        JsonNode details = error(r).path("details");
        Set<String> detailFields = StreamSupport.stream(
                        ((Iterable<String>) () -> details.fieldNames()).spliterator(), false)
                .collect(Collectors.toSet());
        assertEquals(Set.of("currentDestinationRevision"), detailFields);
        assertEquals("1", details.path("currentDestinationRevision").asText());

        Dest after = destOf(installation);
        assertEquals(before.revision(), after.revision());
        assertEquals(before.sessionRef(), after.sessionRef());
        assertEquals(before.status(), after.status());
    }

    // ---------------- 6. account switch ----------------

    @Test
    @DisplayName("6 换号（SC-01-17）：同 installationId 由 B 登录登记 → account 变 B、revision +1、旧快照失配")
    void accountSwitchTakesOverAndBumpsRevision() throws Exception {
        String installation = "inst-switch";
        LoginResult loginA = loginAppWithInstallation(newPhone(), installation);
        assertEquals(200, putJson(loginA.accessToken(), installation,
                body(PROVIDER, PLATFORM, registration("a"), "0"), "k-" + UUID.randomUUID())
                .getResponse().getStatus());
        long oldRevision = destOf(installation).revision();
        assertEquals(UUID.fromString(loginA.accountId()), destOf(installation).accountId());

        LoginResult loginB = loginAppWithInstallation(newPhone(), installation);
        MvcResult r = putJson(loginB.accessToken(), installation,
                body(PROVIDER, PLATFORM, registration("b"), "0"), "k-" + UUID.randomUUID());
        assertEquals(200, r.getResponse().getStatus(), r.getResponse().getContentAsString());

        Dest dest = destOf(installation);
        assertEquals(UUID.fromString(loginB.accountId()), dest.accountId());
        assertEquals(oldRevision + 1, dest.revision());
        assertEquals("active", dest.status());
        assertNotEquals(String.valueOf(dest.revision()), String.valueOf(oldRevision),
                "账号切换必须递增代次，使账号 A 的旧路由快照失配");
    }

    // ---------------- 7. authorization / invalid subjects ----------------

    @Test
    @DisplayName("7 越权/无效主体：installationId 不符 403 / 云台 403 / 无 token 401 / 伪造字段 400 / ios 400 / 空注册 400 / 缺 key 400")
    void authorizationMatrix() throws Exception {
        LoginResult login = loginAppWithInstallation(newPhone(), "inst-auth");
        String json = body(PROVIDER, PLATFORM, registration("tok"), "0");

        MvcResult mismatch = putJson(login.accessToken(), "inst-other", json,
                "k-" + UUID.randomUUID());
        assertEquals(403, mismatch.getResponse().getStatus());
        assertEquals("CALLER_NOT_ALLOWED", error(mismatch).path("code").asText());
        assertEquals(0, destCount("inst-other"));

        UUID gimbalId = seedGimbal();
        String gimbalToken = gimbalToken(gimbalId);
        MvcResult gimbal = putJson(gimbalToken, "inst-auth", json, "k-" + UUID.randomUUID());
        assertEquals(403, gimbal.getResponse().getStatus());
        assertEquals("CALLER_NOT_ALLOWED", error(gimbal).path("code").asText());
        assertEquals(0, destCount("inst-auth"));

        MvcResult anon = putJson(null, "inst-auth", json, "k-" + UUID.randomUUID());
        assertEquals(401, anon.getResponse().getStatus());
        assertEquals("AUTH_REQUIRED", error(anon).path("code").asText());
        assertEquals(0, destCount("inst-auth"));

        MvcResult forged = putJson(login.accessToken(), "inst-auth",
                JSON.writeValueAsString(Map.of("provider", PROVIDER, "platform", PLATFORM,
                        "registration", registration("tok"), "expectedDestinationRevision", "0",
                        "accountId", UUID.randomUUID().toString())),
                "k-" + UUID.randomUUID());
        assertEquals(400, forged.getResponse().getStatus(), forged.getResponse().getContentAsString());
        assertEquals("INVALID_INPUT", error(forged).path("code").asText());

        assertEquals(400, putJson(login.accessToken(), "inst-auth",
                body(PROVIDER, "ios", registration("tok"), "0"), "k-" + UUID.randomUUID())
                .getResponse().getStatus());
        assertEquals(400, putJson(login.accessToken(), "inst-auth",
                body(PROVIDER, PLATFORM, Map.of(), "0"), "k-" + UUID.randomUUID())
                .getResponse().getStatus());
        assertEquals(400, putJson(login.accessToken(), "inst-auth",
                body(PROVIDER, PLATFORM, registration("tok"), "0"), null)
                .getResponse().getStatus());
        assertEquals(400, putJson(login.accessToken(), "inst-auth",
                body(PROVIDER, PLATFORM, registration("tok"), "00"), "k-" + UUID.randomUUID())
                .getResponse().getStatus());
        assertEquals(0, destCount("inst-auth"));
    }

    // ---------------- 8. idempotency ----------------

    @Test
    @DisplayName("8 幂等：同键同内容重放 → meta.replayed=true 且 revision 不再增；同键不同内容 → 409")
    void idempotencyReplayAndConflict() throws Exception {
        String installation = "inst-idem";
        LoginResult login = loginAppWithInstallation(newPhone(), installation);
        String key = "k-idem-" + UUID.randomUUID();
        String json = body(PROVIDER, PLATFORM, registration("tok"), "0");

        MvcResult first = putJson(login.accessToken(), installation, json, key);
        assertEquals(200, first.getResponse().getStatus());
        assertFalse(JSON.readTree(first.getResponse().getContentAsString())
                .path("meta").path("replayed").asBoolean());

        MvcResult replay = putJson(login.accessToken(), installation, json, key);
        assertEquals(200, replay.getResponse().getStatus(), replay.getResponse().getContentAsString());
        assertTrue(JSON.readTree(replay.getResponse().getContentAsString())
                .path("meta").path("replayed").asBoolean());
        assertEquals("1", data(replay).path("destinationRevision").asText());
        assertEquals(1L, destOf(installation).revision());

        MvcResult conflict = putJson(login.accessToken(), installation,
                body(PROVIDER, PLATFORM, registration("different"), "0"), key);
        assertEquals(409, conflict.getResponse().getStatus(), conflict.getResponse().getContentAsString());
        assertEquals("IDEMPOTENCY_CONTENT_CONFLICT", error(conflict).path("code").asText());
        assertEquals(1L, destOf(installation).revision());
    }

    // ---------------- 9. concurrent first registration ----------------

    @Test
    @DisplayName("9 并发首建（两线程同 installationId 同账号 expected=0）→ 恰好 1 行，无 500")
    void concurrentFirstRegistrationSingleRow() throws Exception {
        String installation = "inst-race";
        LoginResult login = loginAppWithInstallation(newPhone(), installation);
        String json = body(PROVIDER, PLATFORM, registration("tok"), "0");

        int workers = 2;
        ExecutorService pool = Executors.newFixedThreadPool(workers);
        CountDownLatch ready = new CountDownLatch(workers);
        CountDownLatch go = new CountDownLatch(1);
        List<Future<Integer>> futures = new ArrayList<>();
        try {
            for (int i = 0; i < workers; i++) {
                final String key = "k-race-" + i + "-" + UUID.randomUUID();
                futures.add(pool.submit((Callable<Integer>) () -> {
                    ready.countDown();
                    assertTrue(go.await(10, TimeUnit.SECONDS));
                    MvcResult r = putJson(login.accessToken(), installation, json, key);
                    if (r.getResponse().getStatus() == 500) {
                        throw new AssertionError("concurrent first registration returned 500: "
                                + r.getResponse().getContentAsString());
                    }
                    return r.getResponse().getStatus();
                }));
            }
            assertTrue(ready.await(10, TimeUnit.SECONDS));
            go.countDown();
            for (Future<Integer> f : futures) {
                int status = f.get(30, TimeUnit.SECONDS);
                assertTrue(status == 200 || status == 409, "unexpected status " + status);
            }
        } finally {
            pool.shutdownNow();
        }
        assertEquals(1, destCount(installation));
        assertEquals(1L, destOf(installation).revision());
    }

    // ---------------- 10. revoked session ----------------

    @Test
    @DisplayName("10 会话失效后 PUT → 401，T09 在该次 PUT 前后未变")
    void revokedSessionRejected() throws Exception {
        String installation = "inst-revoked";
        LoginResult login = loginAppWithInstallation(newPhone(), installation);
        assertEquals(200, putJson(login.accessToken(), installation,
                body(PROVIDER, PLATFORM, registration("tok"), "0"), "k-" + UUID.randomUUID())
                .getResponse().getStatus());

        MvcResult logout = mockMvc.perform(delete("/api/v1/auth/sessions/current")
                .header("Authorization", "Bearer " + login.accessToken())).andReturn();
        assertEquals(204, logout.getResponse().getStatus());

        Dest before = destOf(installation);
        MvcResult r = putJson(login.accessToken(), installation,
