"""B 包通知/扫描可配置参数（D02/D03 未冻结，默认值仅**联调起点、非承诺**）。

env 一律前缀 ``MVP_NOTIFY_``；生产判定沿用 A 的环境变量习惯
（``MVP_NOTIFY_ENV`` > ``MVP_WORKER_ENVIRONMENT`` > ``APP_ENV``，默认 dev），
**不修改 A 的 config.py**。

投递重试上限/退避沿用 A 的 ``WorkerConfig.max_attempts`` 与
``backoff_base_seconds``→``backoff_cap_seconds``（5s→300s），本模块不自创。
"""
from __future__ import annotations

import os
from dataclasses import dataclass

# --- 非承诺 dev 初值（联调起点；设备/后端冻结 D02/D03 后再定） ---
DEFAULT_OFFLINE_THRESHOLD_SECONDS = 120
DEFAULT_SCAN_INTERVAL_SECONDS = 30
DEFAULT_REMINDER_SUPPRESSION_SECONDS = 3600


def _env_int(name: str, default: int) -> int:
    raw = os.environ.get(name, "").strip()
    return int(raw) if raw else default


def _env_bool(name: str, default: bool) -> bool:
    raw = os.environ.get(name, "").strip().lower()
    if not raw:
        return default
    return raw in ("1", "true", "yes", "on")


def resolve_environment() -> str:
    """生产判定：B 自有 env 优先，其次 A 的 worker environment，再 APP_ENV。"""
    raw = (
        os.environ.get("MVP_NOTIFY_ENV")
        or os.environ.get("MVP_WORKER_ENVIRONMENT")
        or os.environ.get("APP_ENV")
        or "dev"
    )
    return raw.strip().lower()


def is_production() -> bool:
    return resolve_environment() in ("production", "prod")


@dataclass(frozen=True)
class NotificationSettings:
    """B 自有通知/扫描配置（不可变；构造即定型）。"""

    # 离线判定阈值（秒）：last_seen_at 早于 now-阈值 且状态 online → 判离线
    offline_threshold_seconds: int = DEFAULT_OFFLINE_THRESHOLD_SECONDS
    # 进程内周期扫描建议间隔（秒）；总协调在集成时接入，本模块不自行起常驻线程
    scan_interval_seconds: int = DEFAULT_SCAN_INTERVAL_SECONDS
    # 重复提醒抑制间隔（秒）：**仅保留语义**，实际去重由 T10 复合唯一键完成
    reminder_suppression_seconds: int = DEFAULT_REMINDER_SUPPRESSION_SECONDS
    # unknown 对账策略：检测到 sending 崩溃残留时是否先查通道回执
    reconcile_unknown: bool = True
    # 回执 not_found 时是否允许用**同一** provider key 做有限重发
    resend_on_not_found: bool = True
    # 运行环境（dev/test 允许替身；production fail-closed）
    environment: str = "dev"

    @property
    def production(self) -> bool:
        return self.environment in ("production", "prod")

    def to_dict(self) -> dict[str, object]:
        return {
            "offline_threshold_seconds": self.offline_threshold_seconds,
            "scan_interval_seconds": self.scan_interval_seconds,
            "reminder_suppression_seconds": self.reminder_suppression_seconds,
            "reconcile_unknown": self.reconcile_unknown,
            "resend_on_not_found": self.resend_on_not_found,
            "environment": self.environment,
        }


def load_settings() -> NotificationSettings:
    """从 env 装载；默认值均为联调起点（非承诺）。"""
    return NotificationSettings(
        offline_threshold_seconds=_env_int(
            "MVP_NOTIFY_OFFLINE_THRESHOLD_SECONDS", DEFAULT_OFFLINE_THRESHOLD_SECONDS
        ),
        scan_interval_seconds=_env_int(
            "MVP_NOTIFY_SCAN_INTERVAL_SECONDS", DEFAULT_SCAN_INTERVAL_SECONDS
        ),
        reminder_suppression_seconds=_env_int(
            "MVP_NOTIFY_REMINDER_SUPPRESSION_SECONDS", DEFAULT_REMINDER_SUPPRESSION_SECONDS
        ),
        reconcile_unknown=_env_bool("MVP_NOTIFY_RECONCILE_UNKNOWN", True),
        resend_on_not_found=_env_bool("MVP_NOTIFY_RESEND_ON_NOT_FOUND", True),
        environment=resolve_environment(),
    )

"""推送通道端口 + 明确命名的 dev/test 替身（C4；推送通道未选定）。

- 端口 :class:`PushProvider`：``deliver``（锁外发送）+ ``query_receipt``（崩溃后对账）。
- 替身 :class:`DevTestDoublePushProvider`：可配置产生四态
  ``accepted/delivered/rejected/unknown``，并可配置回执
  ``accepted/delivered/not_found``；记录调用以供测试断言"不误发"。
- 生产 fail-closed：``app.env=production`` 且无真实 provider 配置时
  :func:`build_push_provider` 立即抛错，绝不默认放行（本 MVP 未实现真实 provider）。
"""
from __future__ import annotations

import os
from dataclasses import dataclass, field
from typing import Any, Mapping, Protocol, runtime_checkable

from .config import NotificationSettings

# 投递结果种类（T10.status 由 handler 映射）
KIND_ACCEPTED = "accepted"      # 可信受理 ID → submitted
KIND_DELIVERED = "delivered"    # 可信送达回执 → delivered
KIND_REJECTED = "rejected"      # 永久失败 → failed
KIND_TRANSIENT = "transient"    # 明确未受理的瞬时失败 → 退避重试
KIND_UNKNOWN = "unknown"        # 超时/不确定 → unknown，不盲目重发

# 回执查询结果种类
RECEIPT_ACCEPTED = "accepted"
RECEIPT_DELIVERED = "delivered"
RECEIPT_NOT_FOUND = "not_found"

_DELIVER_MODES = frozenset(
    {KIND_ACCEPTED, KIND_DELIVERED, KIND_REJECTED, KIND_TRANSIENT, KIND_UNKNOWN}
)
_RECEIPT_MODES = frozenset({RECEIPT_ACCEPTED, RECEIPT_DELIVERED, RECEIPT_NOT_FOUND})


@dataclass(frozen=True)
class PushOutcome:
    kind: str
    provider_message_id: str | None = None
    reason: str | None = None


@dataclass(frozen=True)
class ReceiptOutcome:
    kind: str
    provider_message_id: str | None = None


@dataclass
class PushCall:
    """替身记录的一次发送（供测试断言内容合规与调用次数）。"""

    provider_message_key: str
    text: str
    registration: Mapping[str, Any]


@runtime_checkable
class PushProvider(Protocol):
    def deliver(
        self, *, registration: Mapping[str, Any], text: str, provider_message_key: str
    ) -> PushOutcome: ...

    def query_receipt(self, provider_message_key: str) -> ReceiptOutcome: ...


class DevTestDoublePushProvider:
    """明确命名的 dev/test 替身——**不代表生产可用**。"""

    def __init__(self, *, mode: str = KIND_ACCEPTED, receipt_mode: str = RECEIPT_NOT_FOUND) -> None:
        if mode not in _DELIVER_MODES:
            raise ValueError(f"unknown push double mode: {mode}")
        if receipt_mode not in _RECEIPT_MODES:
            raise ValueError(f"unknown push receipt mode: {receipt_mode}")
        self.mode = mode
        self.receipt_mode = receipt_mode
        self.calls: list[PushCall] = []
        self.receipt_queries: list[str] = []

    # 测试辅助
    def set_mode(self, mode: str) -> None:
        if mode not in _DELIVER_MODES:
            raise ValueError(f"unknown push double mode: {mode}")
        self.mode = mode

    def set_receipt_mode(self, receipt_mode: str) -> None:
        if receipt_mode not in _RECEIPT_MODES:
            raise ValueError(f"unknown push receipt mode: {receipt_mode}")
        self.receipt_mode = receipt_mode

    def deliver(
        self, *, registration: Mapping[str, Any], text: str, provider_message_key: str
    ) -> PushOutcome:
        self.calls.append(
            PushCall(provider_message_key=provider_message_key, text=text, registration=registration)
        )
        if self.mode == KIND_ACCEPTED:
            return PushOutcome(KIND_ACCEPTED, provider_message_id=f"acc-{provider_message_key}")
        if self.mode == KIND_DELIVERED:
            return PushOutcome(KIND_DELIVERED, provider_message_id=f"dlv-{provider_message_key}")
        if self.mode == KIND_REJECTED:
            return PushOutcome(KIND_REJECTED, reason="provider_rejected")
        if self.mode == KIND_TRANSIENT:
            return PushOutcome(KIND_TRANSIENT, reason="provider_transient")
        return PushOutcome(KIND_UNKNOWN, reason="delivery_unknown")

    def query_receipt(self, provider_message_key: str) -> ReceiptOutcome:
        self.receipt_queries.append(provider_message_key)
        if self.receipt_mode == RECEIPT_ACCEPTED:
            return ReceiptOutcome(RECEIPT_ACCEPTED, provider_message_id=f"acc-{provider_message_key}")
        if self.receipt_mode == RECEIPT_DELIVERED:
            return ReceiptOutcome(RECEIPT_DELIVERED, provider_message_id=f"dlv-{provider_message_key}")
        return ReceiptOutcome(RECEIPT_NOT_FOUND)


def build_push_provider(settings: NotificationSettings) -> PushProvider:
    """dev/test → 替身（env 配置四态）；production → fail-closed。

    本 MVP 没有真实推送供应商实现，因此生产一律拒绝，绝不默认放行。
    """
    if settings.production:
        configured = (os.environ.get("MVP_NOTIFY_PUSH_PROVIDER") or "").strip()
        raise RuntimeError(
            "no real PushProvider configured for production"
            f" (MVP_NOTIFY_PUSH_PROVIDER={configured!r}); refusing to send (fail closed)"
        )
    mode = os.environ.get("MVP_NOTIFY_PUSH_DOUBLE", KIND_ACCEPTED).strip() or KIND_ACCEPTED
    receipt_mode = (
        os.environ.get("MVP_NOTIFY_PUSH_RECEIPT", RECEIPT_NOT_FOUND).strip() or RECEIPT_NOT_FOUND
    )
    return DevTestDoublePushProvider(mode=mode, receipt_mode=receipt_mode)

"""``payload-notification-deliver.json`` 严格校验（复用 A system_echo 的
$ref 内联写法；**不修改 system_echo.py**）。

payload 契约（C3）：只允许 ``schema_version``(const 1) + ``notification_id``，
``additionalProperties:false``。违规 → UnsupportedPayload → 运行时
failed/UNSUPPORTED_CONTRACT，不重试。
"""
from __future__ import annotations

import copy
import json
import os
import threading
from pathlib import Path
from typing import Any, Optional

from jsonschema import Draft202012Validator

PAYLOAD_SCHEMA_FILE = "payload-notification-deliver.json"
_COMMON_REF_BASE = "urn:mvp:contracts:schemas:common.json"


def contracts_dir() -> Path:
    env = os.environ.get("MVP_CONTRACTS_DIR")
    if env:
        return Path(env)
    return Path(__file__).resolve().parents[5] / "backend" / "contracts"


def _load_schema(filename: str) -> dict[str, Any]:
    path = contracts_dir() / "schemas" / filename
    with path.open("r", encoding="utf-8") as fh:
        return json.loads(fh.read())


def _resolve_common_ref(ref: str, common: dict[str, Any]) -> dict[str, Any]:
    if not ref.startswith(_COMMON_REF_BASE + "#"):
        raise ValueError(f"unsupported $ref: {ref}")
    node: Any = common
    for part in ref[len(_COMMON_REF_BASE) + 1 :].strip("/").split("/"):
        node = node[part]
    return node


def _inline_refs(node: Any, common: dict[str, Any]) -> Any:
    if isinstance(node, list):
        return [_inline_refs(x, common) for x in node]
    if not isinstance(node, dict):
        return node
    ref = node.get("$ref")
    if isinstance(ref, str) and ref.startswith(_COMMON_REF_BASE + "#"):
        merged = _inline_refs(copy.deepcopy(_resolve_common_ref(ref, common)), common)
        for key, value in node.items():
            if key != "$ref":
                merged[key] = _inline_refs(value, common)
        return merged
    return {k: _inline_refs(v, common) for k, v in node.items()}


class PayloadValidationError(ValueError):
    """payload 违反契约（由 handler 转成 UnsupportedPayload）。"""


class NotificationDeliverPayloadValidator:
    """惰性构建并缓存 draft 2020-12 validator（线程安全）。"""

    def __init__(self) -> None:
        self._validator: Optional[Draft202012Validator] = None
        self._lock = threading.Lock()

    def _get_validator(self) -> Draft202012Validator:
        if self._validator is None:
            with self._lock:
                if self._validator is None:
                    common = _load_schema("common.json")
                    schema = _inline_refs(_load_schema(PAYLOAD_SCHEMA_FILE), common)
                    self._validator = Draft202012Validator(schema)
        return self._validator

    def validate(self, payload: object) -> None:
        if not isinstance(payload, dict):
            raise PayloadValidationError("payload: not an object")
        validator = self._get_validator()
        errors = sorted(validator.iter_errors(payload), key=lambda e: list(e.absolute_path))
        if errors:
            # 只输出错误路径与校验关键字，绝不输出 payload 值（日志禁内容）
            joined = "; ".join(
                f"{e.json_path or '$'}: {e.validator or 'schema'} violated" for e in errors[:5]
            )
            raise PayloadValidationError(f"{PAYLOAD_SCHEMA_FILE}: {joined}")

"""``notification.deliver``：通知投递 handler（DD 9.5；lane-m5 第二部分）。

投递安全不变式：
- **锁外**先核实会话，再在短事务内按锁顺序 ``T03 gimbals → T09
  notification_destinations → T10 notifications`` 逐表 ``SELECT ... FOR UPDATE``
  重检绑定/目标/会话/episode；任一不匹配 → T10 ``status='cancelled'`` +
  有界 ``last_error.reason``，**不调用推送**。
- 提交 ``sending`` 后才发送（发送后崩溃留下可观测 sending）。
- ``submitted`` = 通道可信受理；``delivered`` = 可信送达回执；二者可区分。
- 崩溃后（``sending`` + ``last_attempt_at``）先查回执对账，绝不盲目重发；
  ``not_found`` 且策略允许时用**同一** ``provider_message_key`` 有限重发。
- 推送网络调用在锁外，绝不用长事务包住。
- ``input_revision`` 选择见模块常量 ``INPUT_REVISION_SEMANTICS``：以 T10
  ``destination_revision``（路由快照代次）为准——投递重试期间它稳定，且正是
  实际参与复合唯一键/路由的身份；``attempt_count`` 每次重试都变，无法表达
  "同一逻辑输入"。
"""
from __future__ import annotations

import json
import logging
from dataclasses import dataclass
from typing import Any, Optional

from sqlalchemy import text
from sqlalchemy.engine import Connection, Engine

from . import HandlerContext, HandlerResult, JobFailed, UnsupportedPayload
from ..notifications.config import NotificationSettings, load_settings
from ..notifications.payload_schema import (
    NotificationDeliverPayloadValidator,
    PayloadValidationError,
)
from ..notifications.push import (
    KIND_ACCEPTED,
    KIND_DELIVERED,
    KIND_REJECTED,
    KIND_TRANSIENT,
    KIND_UNKNOWN,
    PushProvider,
    build_push_provider,
)
from ..notifications.session_probe import SessionVerifier, build_session_probe
from ..runtime.rows import JobRow

JOB_TYPE = "notification.deliver"

#: T12.input_revision 语义（协调决策 3 二选一）：destination_revision。
INPUT_REVISION_SEMANTICS = "destination_revision"

#: 最小正文（DD 9.5）：绝不含成员/照片/报告/手机号/账号信息。
PUSH_TEXT = "云台状态异常，请查看"

#: 已是终态，重复领取/重复投递一律 no-op（不重发）。
_TERMINAL_STATUSES = ("submitted", "delivered", "cancelled", "failed")

#: 可被本次尝试推进到 sending 的状态集合。
_SENDABLE_STATUSES = ("pending", "queued", "unknown", "sending")

log = logging.getLogger("mvp_worker.notification.deliver")


class StaleNotification(RuntimeError):
    """完成写回的代次守卫失败：业务事务整体回滚（结果不发布）。"""


@dataclass(frozen=True)
class NotificationRow:
    id: str
    gimbal_id: str
    incident_id: str
    event_type: str
    account_id: str
    binding_revision: int
    destination_id: str
    destination_revision: int
    payload: dict[str, Any]
    status: str
    attempt_count: int
    last_attempt_at: Any
    provider_message_id: Optional[str]
    last_error: Optional[str]
    session_ref: Optional[str]


_SELECT_NOTIFICATION = text(
    """
SELECT id, gimbal_id, incident_id, event_type, account_id, binding_revision,
       destination_id, destination_revision, payload::text AS payload, status,
       attempt_count, last_attempt_at, provider_message_id,
       last_error::text AS last_error, session_ref
FROM notifications
WHERE id = :id
"""
)


def _row_of(m: Any) -> NotificationRow:
    return NotificationRow(
        id=str(m["id"]),
        gimbal_id=str(m["gimbal_id"]),
        incident_id=str(m["incident_id"]),
        event_type=m["event_type"],
        account_id=str(m["account_id"]),
        binding_revision=int(m["binding_revision"]),
        destination_id=str(m["destination_id"]),
        destination_revision=int(m["destination_revision"]),
        payload=json.loads(m["payload"]) if m["payload"] else {},
        status=m["status"],
        attempt_count=int(m["attempt_count"]),
        last_attempt_at=m["last_attempt_at"],
        provider_message_id=m["provider_message_id"],
        last_error=m["last_error"],
        session_ref=m["session_ref"],
    )


class NotificationDeliverHandler:
    name = "notification-deliver"

    def __init__(
        self,
        *,
        push_provider: Optional[PushProvider] = None,
        session_probe: Optional[SessionVerifier] = None,
        settings: Optional[NotificationSettings] = None,
    ) -> None:
        self._push = push_provider
        self._probe = session_probe
        self._settings = settings
        self._validator = NotificationDeliverPayloadValidator()

    # ---------------- handler protocol ----------------

    def validate(self, payload: object) -> None:
        try:
            self._validator.validate(payload)
        except PayloadValidationError as exc:
            raise UnsupportedPayload(str(exc)) from exc

    def handle(self, ctx: HandlerContext, job: JobRow) -> Optional[HandlerResult]:
        notification_id = str(job.payload.get("notification_id"))
        settings = self._settings or load_settings()
        provider, probe = self._deps(ctx.engine, settings)

        row = self._load(ctx.engine, notification_id)
        if row is None:
            raise JobFailed("notification_missing", "notification row not found", retryable=False)
        if row.status in _TERMINAL_STATUSES:
            # 终态幂等：已被正确取消/投递/失败的通知不重复投递（SC-C-04）。
            log.info(
                "notification.terminal_noop",
                extra={"notificationId": row.id, "status": row.status, "jobId": job.id},
            )
            return HandlerResult(business_tx=None)

        if row.status == "sending" and row.last_attempt_at is not None:
            if settings.reconcile_unknown:
                return self._reconcile(ctx, row, provider, settings)
            # 关闭对账策略时绝不盲目重发：标 unknown 收尾。
            return HandlerResult(
                business_tx=self._finalize_tx(
                    row.id, row.attempt_count, "unknown", None,
                    _error("delivery_unknown", "reconciliation disabled by policy", retryable=False),
                )
            )

        new_attempt = row.attempt_count + 1
        return self._precheck_and_send(
            ctx, job, row, provider, probe, new_attempt, f"{row.id}:{new_attempt}"
        )

    # ---------------- dependency wiring ----------------

    def _deps(
        self, engine: Engine, settings: NotificationSettings
    ) -> tuple[PushProvider, SessionVerifier]:
        try:
            provider = self._push or build_push_provider(settings)
            probe = self._probe or build_session_probe(engine, settings)
        except RuntimeError as exc:
            # 生产无真实实现 → fail-closed（绝不默认放行）；永久失败不重试循环。
            raise JobFailed("provider_not_configured", str(exc)[:200], retryable=False) from exc
        return provider, probe

    # ---------------- unknown reconciliation (B-14) ----------------

    def _reconcile(
        self,
        ctx: HandlerContext,
        row: NotificationRow,
        provider: PushProvider,
        settings: NotificationSettings,
    ) -> Optional[HandlerResult]:
        if ctx.abort_event.is_set():
            return None
        provider_key = f"{row.id}:{row.attempt_count}"
        try:
            receipt = provider.query_receipt(provider_key)
        except Exception as exc:  # 探针不可用 → 不臆断，退避重试
            raise JobFailed("receipt_query_failed", type(exc).__name__, retryable=True) from exc

        if receipt.kind == KIND_ACCEPTED:
            return HandlerResult(
                business_tx=self._finalize_tx(
                    row.id, row.attempt_count, "submitted", receipt.provider_message_id, None
                )
            )
        if receipt.kind == KIND_DELIVERED:
            return HandlerResult(
                business_tx=self._finalize_tx(
                    row.id, row.attempt_count, "delivered", receipt.provider_message_id, None
                )
            )
        if receipt.kind == "not_found":
            if settings.resend_on_not_found:
                # 同一 provider key → 通道侧幂等。
                return self._precheck_and_send(
                    ctx, None, row, provider, self._probe, row.attempt_count, provider_key
                )
            return HandlerResult(
                business_tx=self._finalize_tx(
                    row.id, row.attempt_count, "unknown", None,
                    _error("delivery_unknown", "receipt not found after crash", retryable=False),
                )
            )
        raise JobFailed("receipt_query_failed", f"unknown receipt kind {receipt.kind}",
                        retryable=True)

    # ---------------- pre-check + send ----------------

    def _precheck_and_send(
        self,
        ctx: HandlerContext,
        job: Optional[JobRow],
        row: NotificationRow,
        provider: PushProvider,
        probe: Optional[SessionVerifier],
        new_attempt: int,
        provider_key: str,
    ) -> Optional[HandlerResult]:
        # 3. 锁外核实会话（探针异常 → 不投递、可重试）
        try:
            verified = probe is not None and probe.verify(
                account_id=row.account_id,
                destination_id=row.destination_id,
                destination_revision=row.destination_revision,
                session_ref=row.session_ref,
            )
        except Exception as exc:
            raise JobFailed("session_unverified", type(exc).__name__, retryable=True) from exc
        if not verified and not _is_resend(new_attempt, row):
            # 会话探针明确否定：仍走重检（会在事务内判定并 cancelled），不直接发送
            log.info(
                "notification.session_unverified",
                extra={"notificationId": row.id},
            )
        if ctx.abort_event.is_set():
            return None

        # 5. 短事务重检 + 置 sending（提交后才发送）
        outcome = self._recheck_and_mark(ctx.engine, row, new_attempt)
        if outcome.cancelled:
            log.info(
                "notification.cancelled",
                extra={"notificationId": row.id, "reason": outcome.reason},
            )
            return HandlerResult(business_tx=None)
        if ctx.abort_event.is_set():
            return None

        # 6. 锁外发送
        try:
            result = provider.deliver(
                registration=outcome.registration or {},
                text=PUSH_TEXT,
                provider_message_key=provider_key,
            )
        except Exception as exc:
            raise JobFailed("provider_transient", type(exc).__name__, retryable=True) from exc
        if ctx.abort_event.is_set():
            return None

        if result.kind == KIND_ACCEPTED:
            return HandlerResult(
                business_tx=self._finalize_tx(
                    row.id, new_attempt, "submitted", result.provider_message_id, None
                )
            )
        if result.kind == KIND_DELIVERED:
            return HandlerResult(
                business_tx=self._finalize_tx(
                    row.id, new_attempt, "delivered", result.provider_message_id, None
                )
            )
        if result.kind == KIND_REJECTED:
            return HandlerResult(
                business_tx=self._finalize_tx(
                    row.id, new_attempt, "failed", None,
                    _error("provider_rejected", result.reason or "provider rejected",
                           retryable=False),
                )
            )
        if result.kind == KIND_UNKNOWN:
            return HandlerResult(
                business_tx=self._finalize_tx(
                    row.id, new_attempt, "unknown", None,
                    _error("delivery_unknown", result.reason or "delivery unknown",
                           retryable=False),
                )
            )
        if result.kind == KIND_TRANSIENT:
            exhausted = job is not None and job.attempt_count >= job.max_attempts
            if exhausted:
                # T12 将落 failed；先把 T10 从 sending 收尾，避免永久卡在 sending。
                self._mark_terminal(
                    ctx.engine, row.id, new_attempt, "failed",
                    _error("provider_transient", result.reason or "provider transient",
                           retryable=False),
                )
            raise JobFailed("provider_transient", result.reason or "provider transient",
                            retryable=True)
        raise JobFailed("provider_transient", f"unknown outcome kind {result.kind}",
                        retryable=True)

    # ---------------- short transactional re-check ----------------

    @dataclass
    class _Recheck:
        cancelled: bool
        reason: Optional[str] = None
        registration: Optional[dict[str, Any]] = None

    def _recheck_and_mark(
        self, engine: Engine, row: NotificationRow, new_attempt: int
    ) -> "NotificationDeliverHandler._Recheck":
        with engine.begin() as conn:
            t03 = conn.execute(
                text(
                    "SELECT bound_account_id, binding_revision,"
                    " active_incidents::text AS active_incidents"
                    " FROM gimbals WHERE id = :gid FOR UPDATE"
                ),
                {"gid": row.gimbal_id},
            ).mappings().first()
            t09 = conn.execute(
                text(
                    "SELECT account_id, destination_revision, session_ref, status,"
                    " registration::text AS registration"
                    " FROM notification_destinations WHERE id = :did FOR UPDATE"
                ),
                {"did": row.destination_id},
            ).mappings().first()
            t10 = conn.execute(
                text(
                    "SELECT status, attempt_count FROM notifications"
                    " WHERE id = :nid FOR UPDATE"
                ),
                {"nid": row.id},
            ).mappings().first()
            if t10 is None:
                raise JobFailed("notification_missing", "notification disappeared", retryable=False)

            reason = self._mismatch(row, t03, t09)
            if reason is not None:
                conn.execute(
                    text(
                        "UPDATE notifications SET status = 'cancelled',"
                        " last_error = CAST(:err AS jsonb), updated_at = now()"
                        " WHERE id = :nid AND status IN"
                        " ('pending','queued','sending','unknown')"
                    ),
                    {"err": json.dumps(_error("route_recheck_failed", reason, retryable=False,
                                              response_code="route_recheck_failed",
                                              reason=reason)),
                     "nid": row.id},
                )
                return NotificationDeliverHandler._Recheck(cancelled=True, reason=reason)

            res = conn.execute(
                text(
                    "UPDATE notifications SET status = 'sending',"
                    " attempt_count = :newatt, last_attempt_at = now(), updated_at = now()"
                    " WHERE id = :nid AND status IN ('pending','queued','sending','unknown')"
                    " AND attempt_count = :oldatt"
                ),
                {"newatt": new_attempt, "nid": row.id, "oldatt": row.attempt_count},
            )
            if res.rowcount == 0:
                raise JobFailed("delivery_contended", "concurrent delivery attempt",
                                retryable=True)
            registration = json.loads(t09["registration"]) if t09 and t09["registration"] else {}
        return NotificationDeliverHandler._Recheck(cancelled=False, registration=registration)

    @staticmethod
    def _mismatch(row: NotificationRow, t03: Any, t09: Any) -> Optional[str]:
        if t03 is None:
            return "binding_changed"
        if t03["bound_account_id"] is None or str(t03["bound_account_id"]) != row.account_id:
            return "binding_changed"
        if int(t03["binding_revision"]) != row.binding_revision:
            return "binding_changed"
        if t09 is None:
            return "destination_changed"
        if str(t09["account_id"]) != row.account_id:
            return "destination_changed"
        if int(t09["destination_revision"]) != row.destination_revision:
            return "destination_changed"
        if t09["status"] != "active":
            return "destination_changed"
        if (t09["session_ref"] or None) != (row.session_ref or None):
            return "session_changed"
        if not _episode_active(t03["active_incidents"], row.incident_id):
            return "incident_resolved"
        return None

    # ---------------- final business writes ----------------

    def _finalize_tx(
        self,
        notification_id: str,
        attempt: int,
        status: str,
        provider_message_id: Optional[str],
        last_error: Optional[dict[str, Any]],
    ):
        def tx(conn: Connection) -> None:
            res = conn.execute(
                text(
                    "UPDATE notifications SET status = :st, provider_message_id = :mid,"
                    " last_error = CAST(:err AS jsonb), updated_at = now()"
                    " WHERE id = :nid AND status = 'sending' AND attempt_count = :att"
                ),
                {
                    "st": status,
                    "mid": provider_message_id,
                    "err": None if last_error is None else json.dumps(last_error),
                    "nid": notification_id,
                    "att": attempt,
                },
            )
            if res.rowcount == 0:
                # 代次失效：整体回滚，结果不发布。
                raise StaleNotification(
                    f"notification {notification_id} stale generation on finalize"
                )

        return tx

    def _mark_terminal(
        self,
        engine: Engine,
        notification_id: str,
        attempt: int,
        status: str,
        last_error: dict[str, Any],
    ) -> None:
        with engine.begin() as conn:
            res = conn.execute(
                text(
                    "UPDATE notifications SET status = :st,"
                    " last_error = CAST(:err AS jsonb), updated_at = now()"
                    " WHERE id = :nid AND status = 'sending' AND attempt_count = :att"
                ),
                {"st": status, "err": json.dumps(last_error), "nid": notification_id,
                 "att": attempt},
            )
            if res.rowcount == 0:
                raise StaleNotification(
                    f"notification {notification_id} stale generation on terminal mark"
                )

    # ---------------- load ----------------

    @staticmethod
    def _load(engine: Engine, notification_id: str) -> Optional[NotificationRow]:
        with engine.connect() as conn:
            m = conn.execute(_SELECT_NOTIFICATION, {"id": notification_id}).mappings().first()
        return None if m is None else _row_of(m)


def _is_resend(new_attempt: int, row: NotificationRow) -> bool:
    return new_attempt == row.attempt_count


def _episode_active(active_incidents_text: Optional[str], incident_id: str) -> bool:
    if not active_incidents_text:
        return False
    try:
        data = json.loads(active_incidents_text)
    except (TypeError, ValueError):
        return False
    if not isinstance(data, dict):
        return False
    episodes = data.get("episodes")
    if not isinstance(episodes, dict):
        return False
    episode = episodes.get(incident_id)
    return isinstance(episode, dict) and episode.get("state") == "active"


def _error(
    response_code: str,
    reason: str,
    *,
    retryable: bool,
    **extra: Any,
) -> dict[str, Any]:
    err: dict[str, Any] = {"code": response_code, "retryable": retryable}
    # route_recheck_failed 的外层 code + reason（其它写 message）
    if extra.get("response_code"):
        err["code"] = extra["response_code"]
    err["reason"] = reason
    return err


